-- If all_md5 differs BEFORE, the live library changed since this package was built (2026-11-21): do not run 21 (it would refuse anyway); rebuild the package.
select (select count(*) from pb_ai.kb_chunks where version = 'b3e91f6c47d2') as rows,
       (select max(ord) from pb_ai.kb_chunks where version = 'b3e91f6c47d2') as max_ord,
       (select n from pb_ai.kb_versions where version = 'b3e91f6c47d2' and active) as kb_n,
       (select md5(string_agg(ord||':'||lib||':'||(chunk::text), '|' order by ord)) from pb_ai.kb_chunks where version = 'b3e91f6c47d2') as all_md5,
       (select count(*) from pb_ai.kb_chunks k join (values (270, $kb$ca-cal-osha-trench-and-confined-3$kb$, md5($kb${"id": "ca-cal-osha-trench-and-confined-3", "url": "https://www.dir.ca.gov/Title8/5155.html", "text": "California's permissible exposure limits (Title 8 section 5155, Table AC-1) are stricter than federal for gases crews meet. Carbon monoxide: Cal/OSHA PEL 25 ppm 8-hour average with a 200 ppm ceiling (federal construction PEL 50 ppm; NIOSH REL 35 ppm, which many monitors use as the alarm). Hydrogen sulfide: Cal/OSHA 10 ppm 8-hour average, 15 ppm short-term (15-minute) limit, and a 50 ppm ceiling never to be exceeded; federal construction 10 ppm. Carbon dioxide: 5,000 ppm PEL, 30,000 ppm STEL. The confined space limits are the same in both systems: oxygen 19.5 to 23.5 percent and 10 percent of the LEL. The app's permit defaults (O2 19.5-23.5, LEL 10, H2S 10, CO 25) already use the Cal/OSHA CO limit everywhere; a company program may set stricter limits, and 15 ppm H2S is a 15-minute limit, not a working level. None of this is a go/no-go: the entry supervisor and the company program decide.", "title": "Cal/OSHA exposure limits that differ from federal: CO 25 ppm, H2S 10/15 ppm (8 CCR 5155)", "topic": "Cal/OSHA (Title 8) rules for trenches and confined spaces in California", "source": "8 CCR 5155 Table AC-1 (carbon monoxide, hydrogen sulfide, carbon dioxide rows); 29 CFR 1926.55 Appendix A; NIOSH Pocket Guide", "confidence": "high"}$kb$::jsonb::text)), (271, $kb$ca-cal-osha-trench-and-confined-4$kb$, md5($kb${"id": "ca-cal-osha-trench-and-confined-4", "url": "https://www.dir.ca.gov/title8/sb4a37.html", "text": "California runs its own confined space rules; for construction work the one that applies is Title 8 Article 37, Confined Spaces in Construction, sections 1950 to 1962 (in effect since December 30, 2015, amended effective January 1, 2026). It mirrors federal 1926 Subpart AA: 1951 definitions, 1952 general requirements (competent person surveys the site, host employer and controlling contractor coordination), 1953 permit-space program, 1954 permitting, 1955 entry permit, 1956 training, 1957-1959 duties of entrants, attendants and entry supervisors, 1960 rescue. Section 5157 is the general industry standard (an owner's plant staff, not the construction crew); 5158 was the construction rule before 2015. Article 37 does not cover excavation work under Article 6 (1950(b)). The duties match the app's permit flow: test from outside in the order oxygen, flammable, toxic (1953(a)(5)(C)); ventilate; continuous monitoring unless periodic is shown to be enough (1953(a)(5)(B)); attendant, retrieval, signed permit, rescue arranged in advance. Sewers cannot be isolated, so monitoring is continuous where entrants work, with an early warning for engulfment (1953(a)(5)(A)).", "title": "Confined spaces on a California construction job: Title 8 Article 37 (sections 1950-1962), not federal Subpart AA", "topic": "Cal/OSHA (Title 8) rules for trenches and confined spaces in California", "source": "8 CCR 1950-1962 (Article 37, Confined Spaces in Construction) incl. 1950(b), 1953(a)(5); 8 CCR 5156(b), 5157, 5158; OSHSB rulemaking effective Jan. 1, 2026", "confidence": "high"}$kb$::jsonb::text)), (306, $kb$confined-space-field-numbers-1$kb$, md5($kb${"id": "confined-space-field-numbers-1", "url": "https://www.osha.gov/laws-regs/regulations/standardnumber/1926/1926.1202", "text": "Numbers the construction confined space rule and the app's permit use: oxygen below 19.5 percent is deficient and above 23.5 percent is enriched (fire hazard); flammable gas or vapor above 10 percent of its lower explosive limit (LEL/LFL) is a hazardous atmosphere (1926.1202; note that in an open excavation 1926.651(g)(1)(iii) uses 20 percent of the LFL as the control point, inside a confined space it is 10 percent); toxic gases above their limits: H2S 10 ppm 8-hour average (1926.55 Appendix A; Cal/OSHA adds a 15 ppm 15-minute limit and a 50 ppm ceiling), CO 50 ppm federal construction PEL (NIOSH REL 35 ppm, which most monitor alarms use; Cal/OSHA PEL 25 ppm, lower than federal OSHA and NIOSH, which the app uses). NIOSH IDLH: H2S 100 ppm, CO 1,200 ppm. These numbers describe a hazardous atmosphere; they do not by themselves make a space safe to enter. The entry supervisor signs the permit when every condition is met: testing at all levels, ventilation, attendant, communication, retrieval, rescue. In California the same duties sit in Title 8 sections 1950 to 1962.", "title": "Confined space entry numbers: O2, LEL, H2S, CO, and what they are not (1926 Subpart AA)", "topic": "Confined space numbers for construction crews (29 CFR 1926 Subpart AA) in one place", "source": "29 CFR 1926.1202 (hazardous atmosphere definition); 1926.651(g)(1)(iii); 1926.55 Appendix A; NIOSH Pocket Guide; 8 CCR 5155 Table AC-1; 8 CCR 1950-1962", "confidence": "high"}$kb$::jsonb::text)), (307, $kb$confined-space-field-numbers-2$kb$, md5($kb${"id": "confined-space-field-numbers-2", "url": "https://www.osha.gov/laws-regs/regulations/standardnumber/1926/1926.1204", "text": "Before entry the atmosphere is tested from outside with a calibrated, bump-tested direct-reading instrument in this order: oxygen first (a flammable sensor needs oxygen to read right), then flammable gases and vapors, then toxics (1926.1204(e)(3); same as 1910.146(d)(5)(iii) and Cal/OSHA 1953(a)(5)(C)). Test top, middle and bottom: H2S and CO2 settle low, methane rises. The construction rule requires continuous monitoring of atmospheric hazards during entry unless the employer can show that continuous equipment is not commercially available or that periodic monitoring is frequent enough to control the hazard (1926.1204(e)(2)). Where the space cannot be isolated, such as a sewer, pre-entry testing is done to the extent feasible, monitoring where entrants work is continuous (periodic only if continuous equipment is not available), and an early-warning system for engulfment is required (1926.1204(e)(1)). Entrants or their representative may watch the testing and must get the results (1926.1204(e)(4) to (e)(6)). Record readings on the permit at the interval it sets; the app flags a reading outside the limits and blocks check-in until a fresh good test is logged.", "title": "Test order and continuous monitoring: oxygen, then flammable, then toxic (1926.1204(e))", "topic": "Confined space numbers for construction crews (29 CFR 1926 Subpart AA) in one place", "source": "29 CFR 1926.1204(e)(1) to (e)(6); 1910.146(d)(5); 8 CCR 1953(a)(5)", "confidence": "high"}$kb$::jsonb::text)), (308, $kb$confined-space-field-numbers-3$kb$, md5($kb${"id": "confined-space-field-numbers-3", "url": "https://www.osha.gov/laws-regs/regulations/standardnumber/1926/1926.1211", "text": "1926.1211(c): to make non-entry rescue possible, retrieval systems or methods must be used whenever an authorized entrant enters a permit space, unless the retrieval equipment would increase the overall risk of entry or would not contribute to the rescue. Each authorized entrant wears a chest or full-body harness with the retrieval line attached at the center of the back near shoulder level, above the head, or at another point the employer can show gives a profile small enough to pull the entrant out; wristlets or anklets only if the employer can show a harness is infeasible or creates a greater hazard. The other end goes to a mechanical device or fixed point outside the space so rescue can start the moment the rescuer knows it is needed, and a mechanical device (tripod and winch, davit) must be available for vertical permit spaces more than 5 ft deep. That covers every manhole and most vaults. The attendant stays outside until relieved and performs non-entry rescue only (1926.1209(d), (i)); a trained, equipped rescue team does entry rescue. The app's permit roster assumes the retrieval system is set before the first check-in; if it is not on site, there is no entry.", "title": "Retrieval systems: harness, line, and a winch for vertical spaces over 5 ft (1926.1211(c))", "topic": "Confined space numbers for construction crews (29 CFR 1926 Subpart AA) in one place", "source": "29 CFR 1926.1211(c)(1), (c)(2); 1926.1209(d), (i), (j)", "confidence": "high"}$kb$::jsonb::text)), (309, $kb$confined-space-field-numbers-4$kb$, md5($kb${"id": "confined-space-field-numbers-4", "url": "https://www.osha.gov/laws-regs/regulations/standardnumber/1926/1926.1205", "text": "Entry means the action by which any part of a person passes through an opening into a permit space, and it is considered to have occurred as soon as any part of the body breaks the plane of the opening, whether or not it was intentional or any work is done (1926.1202): leaning in to read a gauge, reaching down to grab a tool, or putting a head in a manhole is an entry and needs the permit conditions met. The entry permit must be signed by the entry supervisor before entry, posted or otherwise available at the entrance for the entry's duration, canceled when the work is done or when a condition not allowed by the permit arises, and the canceled permits kept for at least 1 year for the annual program review (1926.1205(f)); problems met during the entry are written on the canceled permit so the program can be fixed. The app keeps every closed permit in Records and never deletes it. A new condition (alarm, weather, a new hazard) means out, cancel, re-evaluate, new permit.", "title": "Entry is breaking the plane; permits are canceled when done and kept 1 year (1926.1202, 1926.1205)", "topic": "Confined space numbers for construction crews (29 CFR 1926 Subpart AA) in one place", "source": "29 CFR 1926.1202 (entry), 1926.1205(e), (f), 1926.1206", "confidence": "high"}$kb$::jsonb::text)), (310, $kb$confined-space-field-numbers-5$kb$, md5($kb${"id": "confined-space-field-numbers-5", "url": "https://www.osha.gov/laws-regs/regulations/standardnumber/1926/1926.1211", "text": "1926.1211(a): an employer that designates an outside rescue service (the fire department, a contract team) must first evaluate its ability to respond in a timely manner, considering the hazards of this space (minutes matter for an atmosphere hazard), and its ability to rescue from this type of space (vertical manhole, deep wet well); select a service that can; tell the service about the hazards; and give it access to the space for a practice rescue. OSHA's non-mandatory Appendix F to 1910.146 says plainly that merely posting the service's number or planning to rely on 911 at the time of an emergency does not comply. In practice: call the responding station before the job to confirm they do confined space rescue and their response time, write it on the permit, keep the non-entry retrieval set up, and know the address and the nearest cross street (the app's EMERGENCY button shows a script). If the service cannot respond in time for the hazard, entry waits. Cal/OSHA's version is Title 8 section 1960.", "title": "Rescue has to be arranged before entry; 911 alone is not a plan (1926.1211(a))", "topic": "Confined space numbers for construction crews (29 CFR 1926 Subpart AA) in one place", "source": "29 CFR 1926.1211(a); 1910.146 Appendix F; 8 CCR 1960", "confidence": "high"}$kb$::jsonb::text)), (311, $kb$confined-space-field-numbers-6$kb$, md5($kb${"id": "confined-space-field-numbers-6", "url": "https://www.osha.gov/laws-regs/regulations/standardnumber/1926/1926.1203", "text": "1926.1203(e) lets an employer enter a permit space without a full permit only when all of these hold: all physical hazards have been eliminated or isolated so the only hazard is an actual or potential hazardous atmosphere; continuous forced-air ventilation alone keeps the space safe; monitoring and inspection data support that and are documented; if an initial entry is needed to get the data it is a full permit entry; any condition making it unsafe to remove the cover is eliminated first and the opening is guarded; the atmosphere is tested before entry and monitored continuously during it (periodic only where the rule's exception applies); the forced air is directed at the immediate work area, comes from a clean source, starts before entry and runs until everyone is out; everyone leaves if a hazardous atmosphere is detected; and a written certification (date, location, signature) is at the entrance. Any engulfment, moving-machinery, electrical or other physical hazard, which includes a sewer where flow can surge, takes it back to a full permit. The entry supervisor and the company program decide; Ask does not.", "title": "Ventilation-only entry (alternate procedures) and when it is not allowed (1926.1203(e))", "topic": "Confined space numbers for construction crews (29 CFR 1926 Subpart AA) in one place", "source": "29 CFR 1926.1203(e)(1), (e)(2)", "confidence": "high"}$kb$::jsonb::text)), (346, $kb$confined-space-silica-1$kb$, md5($kb${"id": "confined-space-silica-1", "url": "https://www.osha.gov/confined-spaces", "text": "Manholes, vaults, wet wells and large pipes are typically confined spaces: large enough to enter, limited entry and exit, and not designed for continuous occupancy. OSHA's construction confined space standard (29 CFR 1926 Subpart AA) requires a competent person to identify confined spaces, evaluate hazards and, for permit-required spaces (hazardous atmosphere, engulfment, entrapment or other serious hazards), use a written program, entry permits, trained entrants, attendants and entry supervisors, atmospheric testing, ventilation and rescue arrangements. Sewer manholes are usually permit-required because of hydrogen sulfide, methane and low oxygen. Use the app's confined space permit tool and your company's program before any entry. This chunk is a plain-language overview; the OSHA standard governs.", "title": "Confined spaces on utility jobs: manholes and vaults", "topic": "Confined spaces and silica (overview)", "source": "OSHA 29 CFR 1926 Subpart AA, Confined Spaces in Construction", "confidence": "medium"}$kb$::jsonb::text)), (347, $kb$confined-space-silica-2$kb$, md5($kb${"id": "confined-space-silica-2", "url": "https://www.osha.gov/confined-spaces", "text": "Before entering a confined space, test the atmosphere with a calibrated, bump-tested multi-gas meter from outside, at several levels (top, middle, bottom, since gases layer). Test in this order: oxygen first, then flammable gases, then toxic gases. OSHA's confined space rules treat as hazardous: oxygen below 19.5% or above 23.5%; flammable gas or vapor above 10% of its lower flammable limit; and toxic gases above their permissible exposure limits (for example hydrogen sulfide and carbon monoxide; check current OSHA limits and your company's alarm settings). Keep monitoring continuously during entry, ventilate with a blower drawing fresh air, and leave immediately if the alarm sounds. The attendant stays outside and never enters for rescue without proper equipment and training.", "title": "Confined spaces: atmospheric testing order and limits", "topic": "Confined spaces and silica (overview)", "source": "OSHA 29 CFR 1926 Subpart AA, Confined Spaces in Construction", "confidence": "medium"}$kb$::jsonb::text)), (2833, $kb$sp-wa-confined-1$kb$, md5($kb${"id": "sp-wa-confined-1", "url": "https://www.law.cornell.edu/regulations/washington/WAC-296-809-50004", "kind": "summary", "text": "Washington has one confined space rule for all industries, chapter 296-809 WAC, instead of adopting the federal construction rule. As read on November 19, 2026: the permit carries the same 15 items as the federal general industry list, in a different order (WAC 296-809-50004), and the testing-equipment item names equipment able to detect a rise in atmospheric hazard if ventilation stops, which is federal construction item (e). The permit is available at entry (296-809-50002(5)), problems met during entry are noted on it (50002(7)), and it is kept 1 year (50006(2)). Air is tested with a calibrated, direct-reading instrument (296-809-60004(3)(a)). OSHA's adoption table lists this state's rule as different from the federal construction rule but at least as effective. The app's permit form covers these items. The chapter was not re-read on 2026-11-20.", "tier": "core", "state": "WA", "title": "Washington confined space rule (chapter 296-809 WAC)", "topic": "State safety plan: confined space", "source": "WAC 296-809-50002, 296-809-50004, 296-809-50006, 296-809-60004", "checked": "2026-11-20", "edition": "Chapter 296-809 WAC, read 2026-11-19", "license": "gov-state", "confidence": "medium", "supersedes": "plan-wa-confined-1"}$kb$::jsonb::text)), (2922, $kb$osha-pl-cs-scope-1$kb$, md5($kb${"id": "osha-pl-cs-scope-1", "url": "https://www.ecfr.gov/current/title-29/subtitle-B/chapter-XVII/part-1926/subpart-AA", "kind": "summary", "text": "29 CFR 1926 Subpart AA (1926.1201 to 1926.1213, in effect since August 3, 2015) protects employees doing construction work at a site with one or more confined spaces. The rule's own examples include manholes, sewers, storm drains, pits, vaults, tanks, lift stations and pipe. It does not apply to construction work regulated by Subpart P (excavations), Subpart S (underground construction, caissons, cofferdams and compressed air) or Subpart Y (diving) (1926.1201(b)). So an open trench is under the excavation rule, but a manhole, a vault or the inside of a pipe is a confined space even when it sits in an excavation. Where another OSHA rule also covers a hazard in the space, follow both (1926.1201(c)). Maintenance work that is not construction is under the general industry rule, 29 CFR 1910.146.", "tier": "core", "state": "US", "title": "When the construction confined space rule applies, and when it does not", "topic": "Confined space rules (OSHA Subpart AA)", "source": "29 CFR 1926.1201(a)-(c); OSHA Confined Spaces in Construction FAQ", "checked": "2026-11-20", "edition": "eCFR current text, read 2026-11-20", "license": "gov-us", "confidence": "high"}$kb$::jsonb::text)), (2925, $kb$osha-pl-cs-altproc-1$kb$, md5($kb${"id": "osha-pl-cs-altproc-1", "url": "https://www.ecfr.gov/current/title-29/subtitle-B/chapter-XVII/part-1926/subpart-AA", "kind": "summary", "text": "29 CFR 1926.1203(e)(1): an employer may use the shorter alternate procedures only when it can show that all physical hazards in the space are eliminated or isolated through engineering controls so the only hazard is an actual or potential hazardous atmosphere, and that continuous forced air ventilation alone is enough to keep the space safe, backed by monitoring data, with the determination written down and available to each entrant. (e)(2) Then: make it safe to remove the cover; guard the opening at once; test the air before entry \"with a calibrated direct-reading instrument, for oxygen content, for flammable gases and vapors, and for potential toxic air contaminants, in that order\"; no hazardous atmosphere while anyone is inside; continuous forced air ventilation; continuous monitoring; get out at once if a hazard shows up; a safe way in and out; and a written certification with the date, the location and the signature of the person certifying. (g) A permit space may be reclassified as non-permit only when a competent person finds no atmospheric hazard and every other hazard eliminated or isolated without entry, and documents it.", "tier": "core", "state": "US", "title": "Alternate procedures and reclassifying a permit space", "topic": "Confined space rules (OSHA Subpart AA)", "source": "29 CFR 1926.1203(e)(1)-(2), (g)", "checked": "2026-11-20", "edition": "eCFR current text, read 2026-11-20", "license": "gov-us", "confidence": "high"}$kb$::jsonb::text)), (2928, $kb$osha-pl-cs-monitor-1$kb$, md5($kb${"id": "osha-pl-cs-monitor-1", "url": "https://www.law.cornell.edu/cfr/text/29/1926.1204", "kind": "summary", "text": "29 CFR 1926.1204(e). Test before entry is authorized. Test in this order: \"oxygen first, then combustible gases and vapors, then toxic gases and vapors.\" Then monitor continuously where entrants are working, unless the employer can show continuous monitoring equipment is not commercially available or periodic monitoring is enough; then monitor periodically, often enough to be sure conditions stay acceptable. Give entrants or their representative the chance to watch the testing, re-test in front of any entrant who asks because the first test may have been inadequate, and give them the results right away. Where an engulfment hazard cannot be isolated, such as a sewer that can flood, provide an early-warning system that continuously watches for the hazard and alerts entrants and attendants in time to get out. Limits: oxygen 19.5 to 23.5 percent, flammables at or under 10 percent of the LFL. Hydrogen sulfide and carbon monoxide limits come from the exposure limit tables, not from Subpart AA.", "tier": "core", "state": "US", "title": "Working in a live sewer that could flood: OSHA early-warning system, air testing order, continuous monitoring", "topic": "Confined space rules (OSHA Subpart AA)", "source": "29 CFR 1926.1204(e)(1)-(6); 1926.1202", "checked": "2026-11-20", "edition": "eCFR current text, read 2026-11-20", "license": "gov-us", "confidence": "high"}$kb$::jsonb::text)), (2929, $kb$osha-pl-cs-permit-1$kb$, md5($kb${"id": "osha-pl-cs-permit-1", "url": "https://www.law.cornell.edu/cfr/text/29/1926.1206", "kind": "summary", "text": "29 CFR 1926.1206 lists what the permit identifies: (a) the space; (b) the purpose of entry; (c) the date and authorized duration; (d) the entrants, by name or by a roster or tracking system; (e) how a rise in air hazard is detected if ventilation stops; (f) each attendant by name; (g) each entry supervisor by name, with the signature or initials of each supervisor who authorizes entry; (h) the hazards of the space; (i) the isolation and control measures; (j) the acceptable entry conditions; (k) test results with the tester's name or initials and when; (l) rescue and emergency services and how to summon them; (m) communication procedures; (n) equipment: PPE, testing, communications, alarms, rescue; (o) other information needed for safety; (p) other permits, such as hot work. 1926.1205: the supervisor signs before entry; the completed permit is available to entrants at entry, by posting at the portal or another equally effective way; the duration is no longer than the task needs; problems met during entry are noted on the permit; and \"The entry employer must retain each canceled entry permit for at least 1 year.\" A permit can be suspended instead of cancelled.", "tier": "core", "state": "US", "title": "The entry permit: the 16 items and how long to keep it", "topic": "Confined space rules (OSHA Subpart AA)", "source": "29 CFR 1926.1205(a)-(f); 1926.1206(a)-(p)", "checked": "2026-11-20", "edition": "eCFR current text, read 2026-11-20", "license": "gov-us", "confidence": "high"}$kb$::jsonb::text)), (2932, $kb$osha-pl-cs-rescue-1$kb$, md5($kb${"id": "osha-pl-cs-rescue-1", "url": "https://www.ecfr.gov/current/title-29/subtitle-B/chapter-XVII/part-1926/subpart-AA", "kind": "summary", "text": "29 CFR 1926.1211. (a) An employer who names a rescue service evaluates whether it can respond in time for the hazards and is able to do the rescue, picks one that can, tells it the hazards, gives it access to the spaces to plan and practice, and has it agree to notify the employer right away when it is unavailable. (b) An employer's own rescue team gets PPE and training, first aid and CPR with at least one member currently certified, and a practice rescue at least once every 12 months. (c) \"Non-entry rescue is required unless the retrieval equipment would increase the overall risk of entry or would not contribute to the rescue of the entrant.\" Each entrant wears a chest or full body harness with a retrieval line attached at the center of the back near shoulder level or above the head; the other end is attached to a mechanical device or fixed point outside so rescue can begin as soon as needed. \"A mechanical device must be available to retrieve personnel from vertical type permit spaces more than 5 feet (1.52 meters) deep.\" Calling 911 is not a rescue plan unless that service has been evaluated and has agreed.", "tier": "core", "state": "US", "title": "Confined space rescue: retrieval lines and rescue services", "topic": "Confined space rules (OSHA Subpart AA)", "source": "29 CFR 1926.1211(a)-(d)", "checked": "2026-11-20", "edition": "eCFR current text, read 2026-11-20", "license": "gov-us", "confidence": "high"}$kb$::jsonb::text)), (2977, $kb$sp-ca-confined-1$kb$, md5($kb${"id": "sp-ca-confined-1", "url": "https://www.dir.ca.gov/Title8/1950.html", "kind": "summary", "text": "California's construction confined space rule is 8 CCR 1950 to 1962 (Construction Safety Orders, Article 37), in effect since December 30, 2015. It follows the federal rule, 29 CFR 1926 Subpart AA: the permit items in 8 CCR 1955(a) are the same 16 as federal 1926.1206, the supervisor signs before entry (1954(b)), the permit is available to entrants at entry (1954(c)) and cancelled permits are kept 1 year (1954(f)). It does not apply to work regulated by Article 6 (excavations), the Tunnel Safety Orders, diving operations, or pressurized worksite operations (1950(b)). Its own note lists manholes, sewers, tanks, vaults and similar spaces as examples. Work that is not construction, such as maintenance in an existing system, is under the general industry rule, 8 CCR 5157. Permit item citations come from the read of November 19, 2026; section 1950 was read again on November 20.", "tier": "core", "state": "CA", "title": "California confined space rule for construction (8 CCR 1950 to 1962)", "topic": "State safety plan: confined space", "source": "8 CCR 1950(a)-(c); 8 CCR 1954, 1955; 8 CCR 5157", "checked": "2026-11-20", "edition": "Title 8 CCR, Article 37 operative 12-30-2015 (Register 2016, No. 1)", "license": "gov-state", "effective": "2015-12-30", "confidence": "high"}$kb$::jsonb::text)), (3016, $kb$sp-md-who-1$kb$, md5($kb${"id": "sp-md-who-1", "url": "https://labor.maryland.gov/labor/mosh/moshspecific.shtml", "kind": "summary", "text": "Maryland's plan, MOSH, lists its state-specific regulations in COMAR Title 09, Subtitle 12: employee injury and illness records (09.12.21), fall protection in steel erection (09.12.25), crane safety (09.12.26), tower crane operator certification (09.12.27), tree care (09.12.28), heat stress (09.12.32), access to information on hazardous and toxic substances (09.12.33), field sanitation (09.12.36) and personnel platforms on cranes (09.12.38). The same MOSH page lists Maryland supplements to federal standards, including 29 CFR 1926.651 (excavations), 29 CFR 1926.1201 to 1213 (confined spaces in construction), 29 CFR 1926.62 (lead) and Subpart CC (cranes). The excavation amendments keep the federal 5 ft trench rule and add that protective system records (tabulated data, designs) are kept at the jobsite (see Maryland's trench card); the confined space supplement's text was not read on 2026-11-20, so what it adds is not confirmed: ask MOSH. The old state confined space rule (COMAR 09.12.35) was repealed effective January 2, 2017.", "tier": "core", "state": "MD", "title": "Maryland: MOSH-specific rules and supplements to the federal trench rule", "topic": "State safety plan: who enforces and what differs", "source": "MOSH, Maryland-specific standards page; COMAR 09.12.21-09.12.38", "checked": "2026-11-20", "edition": "MOSH page, read 2026-11-20", "license": "gov-state", "confidence": "medium", "unconfirmed": "yes"}$kb$::jsonb::text)), (3222, $kb$sp-ca-confined-2026-1$kb$, md5($kb${"id": "sp-ca-confined-2026-1", "url": "https://dir.ca.gov/OSHSB/Confined-Spaces-in-Construction.html", "kind": "summary", "text": "California amended its construction confined space rules (8 CCR 1951, 1952, 1953, 1955, 1956, 1960) effective January 1, 2026. Per the Standards Board's Final Statement of Reasons: a competent person surveys the work area for confined spaces that exist when work begins (1952(a)(1)) and inspects often enough to find new ones (1952(a)(2)); evaluation of a space now includes testing to tell a confined space from a permit space (1952(a)(4)); where less than 10 percent LFL cannot be reached the space is inerted and PPE provided (1953); and standby personnel trained, equipped and available to rescue an entrant are required (1960(a)). The Final Statement of Reasons describes no change to the permit items in 1955. Read the amended rule text before relying on wording.", "tier": "core", "state": "CA", "title": "California confined space changes from January 1, 2026: site survey and rescue standby", "topic": "State safety plan: confined space", "source": "OSHSB rulemaking Confined Spaces in Construction, Final Statement of Reasons updated 2025-09-18; effective 2026-01-01", "checked": "2026-11-20", "license": "gov-state", "effective": "2026-01-01", "confidence": "medium"}$kb$::jsonb::text)), (3223, $kb$sp-mi-confined-2$kb$, md5($kb${"id": "sp-mi-confined-2", "url": "https://www.law.cornell.edu/regulations/michigan/Mich-Admin-Code-R-408-43501", "kind": "summary", "text": "Michigan's Construction Safety Standard Part 35, Confined Space in Construction, adopts 29 CFR 1926.1202 (definitions) through 1926.1212 (employee participation) by reference, except as amended in the rules (R 408.43510, via the scope rule R 408.43501(4)). That includes the federal permit items in 1926.1206, so a federal-style entry permit covers Michigan. Part 35 does not apply to work covered by Part 9 (excavation, trenching and shoring), Part 14 (tunnels, shafts, caissons, cofferdams), Part 504 (diving) or Part 665 (underground construction and compressed air); where another standard also covers a confined space hazard, both apply (R 408.43501(2), (3)). Part 35 has three rules: scope, provision of documents, and adopted standards.", "tier": "core", "state": "MI", "title": "Michigan confined space in construction: MIOSHA Part 35 adopts the federal rule", "topic": "State safety plan: confined space", "source": "Mich. Admin. Code R 408.43501, R 408.43505, R 408.43510 (MIOSHA Part 35)", "checked": "2026-11-20", "edition": "Part 35 as posted by Cornell LII, read 2026-11-20", "license": "gov-state", "confidence": "medium"}$kb$::jsonb::text)), (3224, $kb$sp-md-trench-1$kb$, md5($kb${"id": "sp-md-trench-1", "url": "https://labor.maryland.gov/labor/mosh/reqprotect.shtml", "kind": "summary", "text": "Maryland (MOSH) uses the federal excavation rule: a protective system from 5 feet unless the trench is entirely in stable rock (29 CFR 1926.652). Maryland amends 1926.652 on records: the tabulated data used for a protective system, a slope design, the manufacturer's data and any approval to deviate from it, and an engineer's design are kept at the jobsite while the system is being built and after that until it is no longer used; then they may be kept off site but available to the Commissioner of Labor and Industry on request (Maryland amendments to 1926.652(b)(4)(iii), (c)(2)(iii), (c)(4)(iii)). MOSH lists no Maryland supplement to the confined space in construction rule.", "tier": "core", "state": "MD", "title": "Maryland trench rule: federal 5 feet, plus protective system records kept at the jobsite", "topic": "State safety plan: trench and excavation", "source": "MOSH, Maryland amendments to 29 CFR 1926.652; MOSH-specific standards list", "checked": "2026-11-20", "edition": "MOSH web pages, read 2026-11-20", "license": "gov-state", "confidence": "medium"}$kb$::jsonb::text))) t(o, id, m) on k.ord = t.o and k.chunk->>'id' = t.id and md5(k.chunk::text) = t.m where k.version = 'b3e91f6c47d2') as touched_ok,
       (select count(*) from pb_ai.kb_chunks where version = 'b3e91f6c47d2' and chunk->>'id' in ('osha-pl-cs-air-1', 'osha-pl-cs-permit-keep-1', 'osha-pl-cs-retrieval-1', 'osha-pl-cs-reclass-1', 'osha-pl-cs-states-1', 'osha-pl-cs-states-2')) as new_ids_there;
